package circuit

// End-to-end statement tests for the general ADR-0014 bundle shape:
// fixture.json (generated by gen_fixture.py, whose golden derivations are
// asserted byte-equal against the contract's test_hashes.cairo vectors) holds
// an ordinary 2-in/2-out/1-wd bundle and a controlled 1-in/1-out/1-wd bundle.
// Both are solver-checked at production size (4/4/2); the ordinary case is
// Groth16-proven and verified end-to-end. Negative checks reuse the compiled
// system.

import (
	"encoding/json"
	"math/big"
	"os"
	"testing"

	"github.com/consensys/gnark-crypto/ecc"
	"github.com/consensys/gnark/backend/groth16"
	"github.com/consensys/gnark/constraint"
	"github.com/consensys/gnark/frontend"
	"github.com/consensys/gnark/frontend/cs/r1cs"
	"github.com/consensys/gnark/std/math/emulated"
)

type noteJSON struct {
	Inner        string `json:"inner"`
	Salt         string `json:"salt"`
	OwnerPrivKey string `json:"owner_priv"`
	Token        string `json:"token"`
	Amount       int    `json:"amount"`
	Controller   int    `json:"controller"`
	Policy       int    `json:"policy"`
	Leaf         string `json:"leaf"`
	Nullifier    string `json:"nullifier"`
}

type wdJSON struct {
	Token  string `json:"token"`
	Amount int    `json:"amount"`
}

type caseJSON struct {
	TreeRoot             string     `json:"tree_root"`
	LeafIndices          []int      `json:"leaf_indices"`
	Paths                [][]string `json:"paths"`
	Inputs               []noteJSON `json:"inputs"`
	Outputs              []noteJSON `json:"outputs"`
	Withdrawals          []wdJSON   `json:"withdrawals"`
	Controller           int        `json:"controller"`
	Deadline             int        `json:"deadline"`
	Nonce                int        `json:"nonce"`
	TransitionCommitment string     `json:"transition_commitment"`
	Binding              struct {
		ProtocolVersion string `json:"protocol_version"`
		ChainId         string `json:"chain_id"`
		PoolAddress     string `json:"pool_address"`
		ActionsHash     string `json:"actions_hash"`
		Value           string `json:"value"`
	} `json:"binding"`
}

type fixtureJSON struct {
	Ordinary   caseJSON `json:"ordinary"`
	Controlled caseJSON `json:"controlled"`
}

func mustBig(t *testing.T, s string) *big.Int {
	t.Helper()
	x, ok := new(big.Int).SetString(s, 0)
	if !ok {
		t.Fatalf("bad big int %q", s)
	}
	return x
}

func loadFixture(t *testing.T) *fixtureJSON {
	t.Helper()
	data, err := os.ReadFile("fixture.json")
	if err != nil {
		t.Fatalf("run gen_fixture.py first: %v", err)
	}
	var fx fixtureJSON
	if err := json.Unmarshal(data, &fx); err != nil {
		t.Fatal(err)
	}
	return &fx
}

func el(v *big.Int) emulated.Element[StarknetFp] {
	return emulated.ValueOf[StarknetFp](v)
}

func buildAssignment(t *testing.T, c *caseJSON) *SpendStatement {
	t.Helper()
	st := &SpendStatement{
		ProtocolVersion:      el(mustBig(t, c.Binding.ProtocolVersion)),
		ChainId:              el(mustBig(t, c.Binding.ChainId)),
		PoolAddress:          el(mustBig(t, c.Binding.PoolAddress)),
		TreeRoot:             el(mustBig(t, c.TreeRoot)),
		Controller:           el(big.NewInt(int64(c.Controller))),
		Deadline:             el(big.NewInt(int64(c.Deadline))),
		TransitionCommitment: el(mustBig(t, c.TransitionCommitment)),
		StatementBinding:     el(mustBig(t, c.Binding.Value)),
		NIn:                  len(c.Inputs),
		NOut:                 len(c.Outputs),
		NWd:                  len(c.Withdrawals),
		Token:                el(mustBig(t, c.Inputs[0].Token)),
		Nonce:                el(big.NewInt(int64(c.Nonce))),
		ActionsHash:          el(mustBig(t, c.Binding.ActionsHash)),
	}
	// Zero-fill every padded slot first: emulated zero value has nil limbs,
	// and native zero value is a nil interface.
	zeroEl := el(big.NewInt(0))
	for i := 0; i < MAX_IN; i++ {
		st.InSalt[i], st.InOwner[i], st.InAmount[i] = zeroEl, zeroEl, zeroEl
		st.InCtrl[i], st.InPolicy[i], st.Nullifiers[i] = zeroEl, zeroEl, zeroEl
		st.LeafIndices[i] = big.NewInt(0)
		for j := 0; j < TREE_DEPTH; j++ {
			st.Paths[i][j] = zeroEl
		}
	}
	for j := 0; j < MAX_OUT; j++ {
		st.OutInner[j], st.OutAmount[j] = zeroEl, zeroEl
		st.OutCtrl[j], st.OutPolicy[j], st.OutCommitments[j] = zeroEl, zeroEl, zeroEl
	}
	for k := 0; k < MAX_WD; k++ {
		st.WdAmount[k] = zeroEl
	}
	for i, in := range c.Inputs {
		st.InSalt[i] = el(mustBig(t, in.Salt))
		st.InOwner[i] = el(mustBig(t, in.OwnerPrivKey))
		st.InAmount[i] = el(big.NewInt(int64(in.Amount)))
		st.InCtrl[i] = el(big.NewInt(int64(in.Controller)))
		st.InPolicy[i] = el(big.NewInt(int64(in.Policy)))
		st.Nullifiers[i] = el(mustBig(t, in.Nullifier))
		st.LeafIndices[i] = big.NewInt(int64(c.LeafIndices[i]))
		for j, p := range c.Paths[i] {
			st.Paths[i][j] = el(mustBig(t, p))
		}
	}
	for j, out := range c.Outputs {
		st.OutInner[j] = el(mustBig(t, out.Inner))
		st.OutAmount[j] = el(big.NewInt(int64(out.Amount)))
		st.OutCtrl[j] = el(big.NewInt(int64(out.Controller)))
		st.OutPolicy[j] = el(big.NewInt(int64(out.Policy)))
		st.OutCommitments[j] = el(mustBig(t, out.Leaf))
	}
	for k, wd := range c.Withdrawals {
		st.WdAmount[k] = el(big.NewInt(int64(wd.Amount)))
	}
	return st
}

func compileStatement(t *testing.T) constraint.ConstraintSystem {
	t.Helper()
	ccs, err := frontend.Compile(ecc.BN254.ScalarField(), r1cs.NewBuilder, &SpendStatement{})
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("constraints: %d (secret %d, public %d)",
		ccs.GetNbConstraints(), ccs.GetNbSecretVariables(), ccs.GetNbPublicVariables())
	return ccs
}

func expectUnsat(t *testing.T, ccs constraint.ConstraintSystem, a *SpendStatement, label string) {
	t.Helper()
	w, err := frontend.NewWitness(a, ecc.BN254.ScalarField())
	if err != nil {
		t.Fatal(err)
	}
	if err := ccs.IsSolved(w); err == nil {
		t.Fatalf("%s: tampered witness solved the statement", label)
	}
	t.Logf("%s rejected OK", label)
}

func TestSpendStatement(t *testing.T) {
	fx := loadFixture(t)
	for _, output := range fx.Ordinary.Outputs {
		if output.OwnerPrivKey != "" || output.Salt != "" || output.Inner == "" {
			t.Fatal("paying wallet must receive invoices without recipient spending secrets")
		}
	}
	ccs := compileStatement(t)

	ordinary := buildAssignment(t, &fx.Ordinary)
	controlled := buildAssignment(t, &fx.Controlled)

	// Solver-level checks of both bundle shapes at production size.
	w, err := frontend.NewWitness(ordinary, ecc.BN254.ScalarField())
	if err != nil {
		t.Fatal(err)
	}
	if err := ccs.IsSolved(w); err != nil {
		t.Fatal("IsSolved(ordinary):", err)
	}
	t.Log("IsSolved(ordinary 2/2/1) OK")

	wc, err := frontend.NewWitness(controlled, ecc.BN254.ScalarField())
	if err != nil {
		t.Fatal(err)
	}
	if err := ccs.IsSolved(wc); err != nil {
		t.Fatal("IsSolved(controlled):", err)
	}
	t.Log("IsSolved(controlled 1/1/1) OK")

	// Negative battery (solver-level).
	badInvoice := buildAssignment(t, &fx.Ordinary)
	badInvoice.OutInner[0] = el(big.NewInt(123))
	expectUnsat(t, ccs, badInvoice, "invoice does not match output commitment")
	bad := buildAssignment(t, &fx.Ordinary)
	bad.LeafIndices[0] = big.NewInt(int64(fx.Ordinary.LeafIndices[0]) ^ 1)
	expectUnsat(t, ccs, bad, "tampered leaf index")

	bad = buildAssignment(t, &fx.Ordinary)
	bad.InOwner[1] = el(big.NewInt(0x999))
	expectUnsat(t, ccs, bad, "wrong owner key")

	bad = buildAssignment(t, &fx.Ordinary) // conservation: 40 -> 41
	bad.WdAmount[0] = el(big.NewInt(41))
	bad.StatementBinding = el(big.NewInt(0)) // also breaks the binding
	expectUnsat(t, ccs, bad, "inflated withdrawal")

	bad = buildAssignment(t, &fx.Controlled) // controller-signed legs tampered
	bad.TransitionCommitment = el(big.NewInt(0xdead))
	expectUnsat(t, ccs, bad, "tampered transition commitment")

	bad = buildAssignment(t, &fx.Controlled) // wrong nonce -> wrong tc
	bad.Nonce = el(big.NewInt(8))
	expectUnsat(t, ccs, bad, "wrong controller nonce")
}

// TestSpendStatementGroth16 is the heavyweight end-to-end pass: full Groth16
// setup + prove + verify on the production-size (4/4/2) circuit. Run it
// separately: setup on ~12.5 M constraints takes minutes and tens of GB.
func TestSpendStatementGroth16(t *testing.T) {
	fx := loadFixture(t)
	ccs := compileStatement(t)
	ordinary := buildAssignment(t, &fx.Ordinary)
	w, err := frontend.NewWitness(ordinary, ecc.BN254.ScalarField())
	if err != nil {
		t.Fatal(err)
	}

	pk, vk, err := groth16.Setup(ccs)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := groth16.Prove(ccs, pk, w)
	if err != nil {
		t.Fatal("prove:", err)
	}
	pubW, err := w.Public()
	if err != nil {
		t.Fatal(err)
	}
	if err := groth16.Verify(proof, vk, pubW); err != nil {
		t.Fatal("verify:", err)
	}
	t.Log("groth16 prove+verify OK")
}
